package cdoc

import (
	"bytes"
	"crypto"
	"crypto/rand"
	"crypto/sha256"
	"crypto/x509"
	"encoding/hex"
	"encoding/pem"
	"math/big"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	c2 "github.com/aarepuusepp/libcdoc-go/v2/cdoc/cdoc2"
)

// Decrypt fixtures generated by Open-EID's Java implementation through the same
// prepare/token/finish path used by the browser's native reader.
func TestCDOC2IndependentReference(t *testing.T) {
	for _, tc := range []struct{ file, key, hash string }{
		{"ec_simple.cdoc2", "cdoc2client_expired_priv.key", "d17970a5f4be8c4f68c5ba65783e8cae6db138dfa0be3b90fb43778638cdfc0b"},
		{"ec_256_simple.cdoc2", "cdoc2client_256_priv.key", "03018f9e82df7160bc35f0b8d93e5ad0281248c20934cacca1fd8547e1395062"},
		{"rsa_simple.cdoc2", "rsa_priv.pem", "d17970a5f4be8c4f68c5ba65783e8cae6db138dfa0be3b90fb43778638cdfc0b"},
		{"legacy-ec.cdoc2", "cdoc2client_256_priv.key", "26469c4a201230025d07fcb2674bd166c14141e31dcef3de5a663fadfe9ab0a0"},
		{"legacy-rsa.cdoc2", "rsa_priv.pem", "26469c4a201230025d07fcb2674bd166c14141e31dcef3de5a663fadfe9ab0a0"},
	} {
		t.Run(tc.file, func(t *testing.T) {
			load := func(name string) []byte {
				b, e := os.ReadFile(filepath.Join("testdata/cdoc2-reference", name))
				if e != nil {
					t.Fatal(e)
				}
				return b
			}
			block, _ := pem.Decode(load(tc.key))
			if block == nil {
				t.Fatal("missing test key")
			}
			priv, err := x509.ParsePKCS8PrivateKey(block.Bytes)
			if err != nil {
				if block.Type == "RSA PRIVATE KEY" {
					priv, err = x509.ParsePKCS1PrivateKey(block.Bytes)
				} else {
					priv, err = x509.ParseECPrivateKey(block.Bytes)
				}
			}
			if err != nil {
				t.Fatal(err)
			}
			pub := priv.(crypto.Signer).Public()

			// A self-signed certificate is generated ONLY to exercise the client API;
			// the reference recipient is matched by its independently provided public key.
			cert := referenceCertificate(t, priv, pub)
			input := load(tc.file)
			ch, err := PrepareClientUnwrap(input, cert)
			if err != nil {
				t.Fatal(err)
			}
			token := softwareTokenFromKeys(t, priv, cert)
			kek, err := UnwrapTransportKeyWithToken(token, *ch)
			if err != nil {
				t.Fatal(err)
			}
			files, err := FinishClientDecrypt(input, cert, kek)
			if err != nil {
				t.Fatal(err)
			}
			if len(files) != 1 {
				t.Fatal("empty reference payload")
			}
			for _, f := range files {
				sum := sha256.Sum256(f.Content)
				wantName := "README.md"
				if strings.HasPrefix(tc.file, "legacy-") {
					wantName = "legacy.txt"
				}
				if f.Name != wantName || hex.EncodeToString(sum[:]) != tc.hash {
					t.Fatal("reference plaintext mismatch")
				}
			}
			// Both authentication layers must reject mutations without exposing files.
			corrupt := bytes.Clone(input)
			corrupt[len(corrupt)-1] ^= 1
			if out, e := FinishClientDecrypt(corrupt, cert, kek); e == nil || len(out) != 0 {
				t.Fatal("accepted altered payload")
			}
			wrong := bytes.Clone(kek)
			wrong[0] ^= 1
			if out, e := FinishClientDecrypt(input, cert, wrong); e == nil || len(out) != 0 {
				t.Fatal("accepted wrong key")
			}
			r, _ := c2.NewReader(bytes.NewReader(input))
			_, _ = r.ReadHeader()
			locks, _ := r.GetLocks()
			fmk, err := c2.ExtractFMKFromLock(locks[0], priv, nil, "", nil, nil)
			if err != nil {
				t.Fatal(err)
			}
			defer clear(fmk)
			if err = r.BeginDecryption(fmk); err != nil {
				t.Fatal(err)
			}
			defer func() { _ = r.FinishDecryption() }()

		})
	}
}

func referenceCertificate(t *testing.T, priv, pub any) *x509.Certificate {
	t.Helper()
	tmpl := &x509.Certificate{SerialNumber: big.NewInt(1), NotBefore: time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC), NotAfter: time.Date(2040, 1, 1, 0, 0, 0, 0, time.UTC), KeyUsage: x509.KeyUsageKeyAgreement | x509.KeyUsageKeyEncipherment}
	der, e := x509.CreateCertificate(rand.Reader, tmpl, tmpl, pub, priv)
	if e != nil {
		t.Fatal(e)
	}
	cert, e := x509.ParseCertificate(der)
	if e != nil {
		t.Fatal(e)
	}
	return cert
}
